<script setup lang="ts">
import {ref,onMounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ElMessageBox,ElMessage} from 'element-plus';import {request,run} from '../api/client';
const route=useRoute(),router=useRouter(),username=ref('');onMounted(()=>run(async()=>{username.value=(await request('/auth/me')).username}));
function logout(){run(async()=>{await request('/auth/logout','POST');router.push('/login')})}
function password(){run(async()=>{const old=await ElMessageBox.prompt('请输入原密码','修改密码',{inputType:'password'});const next=await ElMessageBox.prompt('新密码至少6位','修改密码',{inputType:'password'});await request('/auth/password','PUT',{oldPassword:old.value,password:next.value});ElMessage.success('密码已修改，请重新登录');router.push('/login')})}
</script>
<template><el-container class="app-shell"><el-aside width="210px"><div class="brand">CertHub <small>证书管理</small></div><el-menu router :default-active="route.path" background-color="#001529" text-color="#bac7d6" active-text-color="#409eff"><el-menu-item index="/certificates/own">自有证书</el-menu-item><el-menu-item index="/certificates/customer">客户证书</el-menu-item><el-menu-item index="/customers">客户管理</el-menu-item><el-menu-item index="/servers">服务器管理</el-menu-item><el-menu-item index="/sync">证书同步</el-menu-item><el-sub-menu index="system"><template #title>系统管理</template><el-menu-item index="/system/audit">审计日志</el-menu-item><el-menu-item index="/system/users">用户管理</el-menu-item><el-menu-item index="/system/smtp">SMTP配置</el-menu-item><el-menu-item index="/system/notifications">通知服务</el-menu-item></el-sub-menu></el-menu></el-aside><el-container><el-header><span>证书管理工作台</span><div><span>{{username}} · 管理员</span><el-button text @click="password">修改密码</el-button><el-button text @click="logout">退出</el-button></div></el-header><el-main><router-view :key="route.path" /></el-main></el-container></el-container></template>

